{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "It could be accepted if the carve-outs below are agreed."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Reduce the basket to about 0.5% of price (AUD 120k) and the de minimis to about AUD 10k."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "ACCEPT",
      "evidence": "18 months for general warranties is acceptable."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Fundamental warranties subject to the general cap and time limits: reject"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Carve out the following: - **Fraud, dishonesty and wilful concealment.**"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "General disclosure of the data room, Accounts, registers and public records (DL §1.1–1.2): reject"
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "**Position:** delete it."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "A **condition precedent**: unconditional written consent from Bluefen in a form satisfactory to the Buyer, acting reasonably"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Payoff letter, deed of release and PPSR discharge at Completion; paid from the price"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "the bonuses to be treated as Transaction Costs or Debt, deducted from the price, and paid through Company payroll at Completion"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Pre-Completion payment plus confirmatory assignment; IP indemnity outside the cap"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "A **specific uncapped indemnity** covering regulatory penalties, notification and remediation costs, third-party claims and customer credits."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "In all cases, add the aggregation clause (item 2) and a conduct-of-business covenant prohibiting further renewals without Buyer consent."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "The default should be the opposite: limitations apply *only* to general Warranty Claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "A self-maintained share register is not enough evidence of title on its own."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax and IP \"settled under the general regime\": reject"
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "A 20% cap for general warranties is within the market range for an AUD 24m deal.",
  "names_manipulation": false
}

